"""ExploreRunner — 探索期离线技能生成。

参考 agentd/explore/explore_runner.py。在探索期（非生产对话）
通过 4 步 Prompt 把一段任务描述固化为可审核的 Skill Package：

1. 概念提取（01_extract_concepts）   → 技能名/意图/关键词/输入
2. DAG 生成（02_generate_dag）      → manifest + action_graph JSON
3. 对抗验证（03_adversarial_check） → 审查未定义变量/危险命令/循环依赖
4. 固化输出（04_finalize_package）  → 修正后写入 explore/output/{skill}/

产出供人工审核后由 scripts/install_skill.py 安装，不自动生效。
"""
import json
import logging
import re
from datetime import datetime
from pathlib import Path

logger = logging.getLogger("agent.explore")

PROMPT_STEPS = [
    ('01_extract_concepts', '概念提取'),
    ('02_generate_dag', 'DAG 生成'),
    ('03_adversarial_check', '对抗验证'),
    ('04_finalize_package', '固化输出'),
]


class ExploreRunner:
    """4 步 Prompt 流水线，产出 Skill Package 到 explore/output/。"""

    def __init__(self, config, llm_client):
        self.config = config
        self.llm = llm_client
        self.prompts_dir = config.base_dir / 'explore' / 'prompts'
        self.output_dir = config.base_dir / 'explore' / 'output'
        self.output_dir.mkdir(parents=True, exist_ok=True)

    # ─────────────────────────────────────────
    # 工具方法
    # ─────────────────────────────────────────
    def _load_prompt(self, name, **variables):
        path = self.prompts_dir / ('%s.md' % name)
        text = path.read_text(encoding='utf-8')
        for key, val in variables.items():
            text = text.replace('{{%s}}' % key, str(val))
        return text

    @staticmethod
    def _parse_json(text):
        """容错解析 LLM 输出的 JSON（剥离 markdown 代码围栏）。"""
        match = re.search(r'```(?:json)?\s*(\{.*?\})\s*```', text, re.DOTALL)
        if match:
            text = match.group(1)
        else:
            start, end = text.find('{'), text.rfind('}')
            if start == -1 or end <= start:
                raise ValueError('LLM 输出中未找到 JSON')
            text = text[start:end + 1]
        return json.loads(text)

    def _ask(self, step_name, prompt_text):
        logger.info('探索步骤 [%s] 调用 LLM ...', step_name)
        result = self.llm.quick_prompt(
            '你是数字员工的技能工程专家，严格按用户要求输出，不要多余解释。',
            prompt_text, skill='explore', category='normal', json_mode=True)
        return result

    # ─────────────────────────────────────────
    # 4 步流水线
    # ─────────────────────────────────────────
    def run(self, task_description):
        """输入任务描述，产出 Skill Package。

        返回 {success, skill_name, dir, issues, report}。
        """
        if not self.config.llm_configured:
            return {'success': False, 'skill_name': None, 'dir': None,
                    'issues': [], 'report': 'LLM 未配置，无法执行技能探索'}

        # Step 1: 概念提取
        concepts = self._parse_json(self._ask(
            '01_extract_concepts',
            self._load_prompt('01_extract_concepts', TASK=task_description)))
        skill_name = concepts.get('skill_name', 'unnamed_skill')

        # Step 2: DAG 生成
        package = self._parse_json(self._ask(
            '02_generate_dag',
            self._load_prompt('02_generate_dag',
                              TASK=task_description,
                              CONCEPTS=json.dumps(concepts, ensure_ascii=False))))
        manifest = package.get('manifest', {})
        action_graph = package.get('action_graph', {})
        manifest.setdefault('name', skill_name)
        manifest.setdefault('version', '0.1.0')

        # Step 3: 对抗验证
        check = self._parse_json(self._ask(
            '03_adversarial_check',
            self._load_prompt('03_adversarial_check',
                              PACKAGE=json.dumps(package, ensure_ascii=False))))
        issues = check.get('issues', [])
        if issues and check.get('fixed_package'):
            fixed = check['fixed_package']
            manifest = fixed.get('manifest', manifest)
            action_graph = fixed.get('action_graph', action_graph)

        # Step 4: 固化输出
        finalize_note = self._ask(
            '04_finalize_package',
            self._load_prompt('04_finalize_package',
                              SKILL=skill_name,
                              ISSUES=json.dumps(issues, ensure_ascii=False)))
        skill_dir = self.output_dir / skill_name
        skill_dir.mkdir(parents=True, exist_ok=True)
        (skill_dir / 'manifest.json').write_text(
            json.dumps(manifest, ensure_ascii=False, indent=2), encoding='utf-8')
        (skill_dir / 'action_graph.json').write_text(
            json.dumps(action_graph, ensure_ascii=False, indent=2), encoding='utf-8')
        report = (
            '# 技能探索报告：%s\n\n- 生成时间：%s\n- 任务描述：%s\n'
            '- 发现问题：%d 个\n- LLM 终审意见：\n%s\n\n'
            '## 审核通过后安装\n```\npython scripts/install_skill.py %s\n```\n'
            % (skill_name, datetime.now().strftime('%Y-%m-%d %H:%M'),
               task_description, len(issues), finalize_note, skill_dir))
        (skill_dir / 'explore_report.md').write_text(report, encoding='utf-8')

        logger.info('技能探索完成: %s → %s（问题 %d 个，待人工审核）',
                    skill_name, skill_dir, len(issues))
        return {'success': True, 'skill_name': skill_name,
                'dir': str(skill_dir), 'issues': issues, 'report': report}

    def list_outputs(self):
        """列出已产出待审核的技能目录。"""
        return sorted(d.name for d in self.output_dir.iterdir()
                      if d.is_dir() and (d / 'manifest.json').exists())
